CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS games (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,seed bigint NOT NULL,current_version integer NOT NULL CHECK (current_version>=1),state jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS game_events (id uuid PRIMARY KEY,game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE,version integer NOT NULL CHECK (version>=1),event_type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(game_id,version));
CREATE TABLE IF NOT EXISTS game_saves (id uuid PRIMARY KEY,game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE,version integer NOT NULL CHECK (version>=1),schema_version integer NOT NULL CHECK (schema_version>=1),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(game_id,version));
CREATE TABLE IF NOT EXISTS refresh_tokens (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,resource_type text NOT NULL,resource_id text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_game_events_game_version ON game_events(game_id,version);CREATE INDEX IF NOT EXISTS idx_game_saves_game_version ON game_saves(game_id,version DESC);CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user ON refresh_tokens(user_id);CREATE INDEX IF NOT EXISTS idx_audit_log_actor_created ON audit_log(actor_id,created_at DESC);
